#!/usr/bin/env python3
"""
gem_init_gen.py - Generate C source from mruby gem mrblib/*.rb files,
and create the summary gems_init.c that calls all gem init functions.

Usage:
  # Process one gem's mrblib (generates <gem>_mrblib.c):
  python3 gem_init_gen.py mrblib --gem-name <name> --gem-dir <path> --output <out.c>

  # Generate gems_init.c (summary init file):
  python3 gem_init_gen.py gems-init --gems <gem1,gem2,...> --output <gems_init.c>
"""

import os
import sys
import argparse
import re


def _gem_func_name(gem_name: str) -> str:
    """Convert gem name to function-safe identifier (hyphens → underscores)."""
    return gem_name.replace("-", "_")


def _ruby_to_c_literal(rb_content: str) -> str:
    """Convert Ruby source text to a C string literal with proper escaping."""
    result = []
    for ch in rb_content:
        if ch == '\\':
            result.append('\\\\')
        elif ch == '"':
            result.append('\\"')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\t':
            result.append('\\t')
        elif ch == '\r':
            result.append('\\r')
        elif '\x00' <= ch <= '\x1f' or '\x7f' <= ch <= '\xff':
            result.append(f'\\x{ord(ch):02x}""')
        else:
            result.append(ch)
    return '"' + ''.join(result) + '"'


def generate_mrblib_c(gem_name: str, gem_dir: str, output_file: str) -> bool:
    """
    Generate a C source file embedding all .rb files from gem's mrblib/.
    Returns True if anything was generated, False if mrblib/ is empty/missing.
    """
    mrblib_dir = os.path.join(gem_dir, "mrblib")
    if not os.path.isdir(mrblib_dir):
        return False

    rb_files = sorted(
        f for f in os.listdir(mrblib_dir) if f.endswith(".rb")
    )
    if not rb_files:
        return False

    func_safe = _gem_func_name(gem_name)

    lines = []
    lines.append('/* Auto-generated by gem_init_gen.py - DO NOT EDIT */')
    lines.append('#include <mruby.h>')
    lines.append('')

    for rb_file in rb_files:
        path = os.path.join(mrblib_dir, rb_file)
        with open(path, "r", encoding="utf-8") as f:
            content = f.read()
        c_literal = _ruby_to_c_literal(content)
        var_name = re.sub(r'[^a-zA-Z0-9_]', '_', f"mrblib_{func_safe}_{rb_file[:-3]}")
        lines.append(f'static const char {var_name}[] = {c_literal};')
        lines.append('')

    lines.append(f'void mrb_load_gem_{func_safe}(mrb_state *mrb)')
    lines.append('{')
    for rb_file in rb_files:
        var_name = re.sub(r'[^a-zA-Z0-9_]', '_', f"mrblib_{func_safe}_{rb_file[:-3]}")
        lines.append(f'  mrb_load_nstring(mrb, {var_name}, sizeof({var_name}) - 1);')
    lines.append('}')

    os.makedirs(os.path.dirname(output_file) or ".", exist_ok=True)
    with open(output_file, "w", encoding="utf-8", newline="\n") as f:
        f.write('\n'.join(lines) + '\n')

    print(f"Generated mrblib: {output_file} ({len(rb_files)} .rb files)")
    return True


def generate_gems_init(gem_names: list, output_file: str):
    """Generate gems_init.c with mrb_init_mrbgems() calling all gem init funcs."""
    lines = []
    lines.append('/* Auto-generated by gem_init_gen.py - DO NOT EDIT */')
    lines.append('#include <mruby.h>')
    lines.append('')

    # Forward declarations
    active_gems = []
    for name in gem_names:
        func_safe = _gem_func_name(name)
        # Check if gem actually has C code (we can't know here; declare anyway)
        lines.append(f'void mrb_{func_safe}_gem_init(mrb_state *mrb);')
        lines.append(f'void mrb_{func_safe}_gem_final(mrb_state *mrb);')
        lines.append(f'void mrb_load_gem_{func_safe}(mrb_state *mrb);')
        active_gems.append(func_safe)
    lines.append('')

    # mrb_init_mrbgems
    lines.append('void mrb_init_mrbgems(mrb_state *mrb)')
    lines.append('{')
    for func_safe in active_gems:
        lines.append(f'  mrb_{func_safe}_gem_init(mrb);')
        lines.append(f'  mrb_load_gem_{func_safe}(mrb);')
    lines.append('}')
    lines.append('')

    # mrb_final_mrbgems
    lines.append('void mrb_final_mrbgems(mrb_state *mrb)')
    lines.append('{')
    for func_safe in active_gems:
        lines.append(f'  mrb_{func_safe}_gem_final(mrb);')
    lines.append('}')

    os.makedirs(os.path.dirname(output_file) or ".", exist_ok=True)
    with open(output_file, "w", encoding="utf-8", newline="\n") as f:
        f.write('\n'.join(lines) + '\n')

    print(f"Generated gems_init: {output_file} ({len(active_gems)} gems)")


def main():
    parser = argparse.ArgumentParser(description="mruby gem init generator")
    sub = parser.add_subparsers(dest="mode", required=True)

    p_mrblib = sub.add_parser("mrblib", help="Generate mrblib C file for a gem")
    p_mrblib.add_argument("--gem-name", required=True)
    p_mrblib.add_argument("--gem-dir", required=True)
    p_mrblib.add_argument("--output", "-o", required=True)

    p_init = sub.add_parser("gems-init", help="Generate gems_init.c")
    p_init.add_argument("--gems", required=True, help="Comma-separated gem names")
    p_init.add_argument("--output", "-o", required=True)

    args = parser.parse_args()

    if args.mode == "mrblib":
        ok = generate_mrblib_c(args.gem_name, args.gem_dir, args.output)
        if not ok:
            # Generate empty stub so mrb_load_gem_<name> is always defined
            func_safe = _gem_func_name(args.gem_name)
            os.makedirs(os.path.dirname(args.output) or ".", exist_ok=True)
            with open(args.output, "w") as f:
                f.write('/* Auto-generated empty stub - no mrblib */\n')
                f.write('#include <mruby.h>\n')
                f.write(f'void mrb_load_gem_{func_safe}(mrb_state *mrb) {{ (void)mrb; }}\n')

    elif args.mode == "gems-init":
        gem_names = [g.strip() for g in args.gems.split(",") if g.strip()]
        generate_gems_init(gem_names, args.output)


if __name__ == "__main__":
    main()
